     1→import { useCallback, useMemo, type ReactNode } from "react";
     2→import { ChevronRight } from "lucide-react";
     3→import { useTranslation } from "react-i18next";
     4→import { useQuery } from "@tanstack/react-query";
     5→import { Button } from "@/components/ui/button";
     6→import { IconDisplay } from "@/components/ui/icon-picker";
     7→import { cn } from "@/lib/utils";
     8→import { useLocalWorkspaces } from "@/hooks/use-workspaces";
     9→import { useDesktopRouting } from "@/hooks/use-desktop-routing";
    10→import { BreadcrumbDropdown } from "./breadcrumb-dropdown";
    11→import {
    12→  getWorkspaceSectionDescriptor,
    13→  resolveSegmentDescriptorId,
    14→  resolvePageIndexBranch,
    15→  type BreadcrumbDropdownItem,
    16→  type DesktopBreadcrumbSegment,
    17→} from "@/navigation/page-index";
    18→import { getGatewayUrl, listPages } from "@/lib/gateway";
    19→import { pageKeys } from "@/hooks/use-pages";
    20→import type { Workspace } from "@/types";
    21→
    22→interface DesktopBreadcrumbBarProps {
    23→  workspace?: Workspace;
    24→  segments?: DesktopBreadcrumbSegment[];
    25→  className?: string;
    26→  centerSlot?: ReactNode;
    27→  rightSlot?: ReactNode;
    28→}
    29→
    30→function inferDescriptorId(href: string, descriptorId?: DesktopBreadcrumbSegment["descriptorId"]) {
    31→  if (descriptorId === "workspace-web") {
    32→    return "workspace-web" as const;
    33→  }
    34→  if (descriptorId === "workspace-page") {
    35→    return "workspace-page" as const;
    36→  }
    37→  if (href.startsWith("/workspace/")) {
    38→    return "workspace" as const;
    39→  }
    40→  return "settings" as const;
    41→}
    42→
    43→export function DesktopBreadcrumbBar({
    44→  workspace,
    45→  segments = [],
    46→  className,
    47→  centerSlot,
    48→  rightSlot,
    49→}: DesktopBreadcrumbBarProps) {
    50→  const { t } = useTranslation();
    51→  const { workspaces, selectWorkspace } = useLocalWorkspaces();
    52→  const {
    53→    openPath,
    54→    openWorkspaceApps,
    55→    openWorkspaceHome,
    56→    openWorkspaceSection,
    57→    popToBreadcrumb,
    58→  } = useDesktopRouting();
    59→  const workspacePath = workspace?.path;
    60→  const { data: pagesResult } = useQuery({
    61→    queryKey: workspacePath ? pageKeys.list(workspacePath) : ["pages", "disabled"],
    62→    queryFn: () => listPages(getGatewayUrl(), workspacePath ?? ""),
    63→    enabled: Boolean(workspacePath),
    64→    staleTime: 30_000,
    65→  });
    66→  const pages = pagesResult?.pages ?? [];
    67→
    68→  const currentSection = useMemo(() => {
    69→    const sectionSegment = segments.find((segment) => {
    70→      const id = resolveSegmentDescriptorId(segment);
    71→      return id?.startsWith("workspace-section:");
    72→    });
    73→    return sectionSegment?.meta?.section;
    74→  }, [segments]);
    75→
    76→  const currentArea = useMemo<"home" | "apps" | "section">(() => {
    77→    const appsHref = workspace?.id
    78→      ? `/workspace/${encodeURIComponent(workspace.id)}/apps`
    79→      : null;
    80→    if (appsHref && segments.some((segment) => segment.href === appsHref)) {
    81→      return "apps";
    82→    }
    83→    if (currentSection) {
    84→      return "section";
    85→    }
    86→    return "home";
    87→  }, [currentSection, segments, workspace?.id]);
    88→
    89→  const currentPageSlug = useMemo(() => {
    90→    const pageSegments = segments.filter((segment) => segment.meta?.pageSlug);
    91→    return pageSegments[pageSegments.length - 1]?.meta?.pageSlug;
    92→  }, [segments]);
    93→
    94→  const currentSettingsSection = useMemo(() => {
    95→    const settingsSegment = segments.find((segment) => segment.href.startsWith("/settings/"));
    96→    if (!settingsSegment) {
    97→      return undefined;
    98→    }
    99→    return settingsSegment.href.split("/settings/")[1] || "general";
   100→  }, [segments]);
   101→
   102→  const navigateWithTab = useCallback(
   103→    (segment: Pick<DesktopBreadcrumbSegment, "href" | "label" | "icon" | "descriptorId" | "meta">) => {
   104→      openPath(segment.href, {
   105→        descriptorId: inferDescriptorId(segment.href, segment.descriptorId),
   106→        title: segment.label,
   107→        icon: segment.icon,
   108→        slug:
   109→          segment.meta?.section ??
   110→          segment.meta?.pageSlug ??
   111→          segment.meta?.agentId ??
   112→          segment.meta?.executorType,
   113→        workspaceId: segment.meta?.workspaceId ?? workspace?.id,
   114→      });
   115→    },
   116→    [openPath, workspace?.id]
   117→  );
   118→
   119→  const handleWorkspaceSelect = useCallback(
   120→    (workspaceId: string) => {
   121→      selectWorkspace(workspaceId);
   122→
   123→      if (currentSection) {
   124→        const descriptor = getWorkspaceSectionDescriptor(currentSection);
   125→        if (descriptor) {
   126→          openWorkspaceSection(workspaceId, descriptor.section);
   127→          return;
   128→        }
   129→      }
   130→
   131→      if (currentArea === "apps") {
   132→        openWorkspaceApps(workspaceId);
   133→        return;
   134→      }
   135→
   136→      openWorkspaceHome(workspaceId);
   137→    },
   138→    [
   139→      currentArea,
   140→      currentSection,
   141→      openWorkspaceApps,
   142→      openWorkspaceHome,
   143→      openWorkspaceSection,
   144→      selectWorkspace,
   145→    ]
   146→  );
   147→
   148→  const handleSectionSelect = useCallback(
   149→    (section: NonNullable<DesktopBreadcrumbSegment["meta"]>["section"], _routePath: string, href: string) => {
   150→      if (!workspace?.id || !section) {
   151→        openPath(href, {
   152→          descriptorId: "workspace",
   153→          title: href,
   154→          workspaceId: workspace?.id,
   155→        });
   156→        return;
   157→      }
   158→
   159→      openWorkspaceSection(workspace.id, section);
   160→    },
   161→    [openPath, openWorkspaceSection, workspace?.id]
   162→  );
   163→
   164→  const rootSegment = useMemo<DesktopBreadcrumbSegment | null>(() => {
   165→    if (!workspace) {
   166→      return null;
   167→    }
   168→
   169→    return {
   170→      id: `workspace:${workspace.id}`,
   171→      label:
   172→        workspace.type === "global"
   173→          ? t("workspace.global", "Global Workspace")
   174→          : workspace.name,
   175→      href: `/workspace/${encodeURIComponent(workspace.id)}`,
   176→      path: workspace.path,
   177→      descriptorId: "workspace",
   178→      icon: {
   179→        type: "lucide",
   180→        value: workspace.type === "global" ? "globe" : "folder-open",
   181→      },
   182→      meta: {
   183→        workspaceId: workspace.id,
   184→      },
   185→    };
   186→  }, [t, workspace]);
   187→
   188→  const renderSegmentButton = (
   189→    segment: DesktopBreadcrumbSegment,
   190→    isCurrent: boolean,
   191→    stackIndex: number
   192→  ) => (
   193→    <Button
   194→      type="button"
   195→      variant="ghost"
   196→      size="sm"
   197→      className={cn(
   198→        "h-8 gap-2 rounded-lg px-2.5 font-medium",
   199→        isCurrent && "bg-accent/70"
   200→      )}
   201→      onClick={() => {
   202→        if (segment.onClick) {
   203→          segment.onClick();
   204→          return;
   205→        }
   206→        if (!isCurrent && stackIndex >= 0) {
   207→          popToBreadcrumb(stackIndex);
   208→          return;
   209→        }
   210→        navigateWithTab(segment);
   211→      }}
   212→      title={segment.path}
   213→    >
   214→      <IconDisplay
   215→        icon={segment.icon}
   216→        size="sm"
   217→        className="text-muted-foreground"
   218→      />
   219→      <span className="max-w-[220px] truncate">{segment.label}</span>
   220→    </Button>
   221→  );
   222→
   223→  const renderDropdown = (
   224→    segment: DesktopBreadcrumbSegment,
   225→    isCurrent: boolean,
   226→    stackIndex: number
   227→  ) => {
   228→    const items = resolvePageIndexBranch({
   229→      segment,
   230→      workspaceId: workspace?.id,
   231→      pages,
   232→      workspaces,
   233→      activeWorkspaceId: workspace?.id,
   234→      currentSection,
   235→      currentArea,
   236→      currentPageSlug,
   237→      currentSettingsSection,
   238→      buildLabel: (key, fallback) => t(key, fallback),
   239→      onSelectWorkspace: handleWorkspaceSelect,
   240→      onSelectSection: handleSectionSelect,
   241→      labelGlobalWorkspace: t("workspace.global", "Global Workspace"),
   242→    });
   243→
   244→    const onDropdownSelect = (item: BreadcrumbDropdownItem) => {
   245→      if (item.onSelect) {
   246→        return;
   247→      }
   248→      if (item.href) {
   249→        if (item.meta?.workspaceId && item.href === `/workspace/${encodeURIComponent(item.meta.workspaceId)}/apps`) {
   250→          openWorkspaceApps(item.meta.workspaceId);
   251→          return;
   252→        }
   253→        navigateWithTab({
   254→          href: item.href,
   255→          label: item.label,
   256→          icon: item.icon,
   257→          descriptorId: item.descriptorId,
   258→          meta: item.meta,
   259→        });
   260→      }
   261→    };
   262→
   263→    return (
   264→      <BreadcrumbDropdown items={items} onSelect={onDropdownSelect}>
   265→        {renderSegmentButton(segment, isCurrent, stackIndex)}
   266→      </BreadcrumbDropdown>
   267→    );
   268→  };
   269→
   270→  const allSegments = rootSegment ? [rootSegment, ...segments] : segments;
   271→
   272→  return (
   273→    <header
   274→      className={cn(
   275→        "grid h-14 grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] items-center gap-4 border-b bg-background px-4",
   276→        className
   277→      )}
   278→    >
   279→      <div className="min-w-0 overflow-x-auto scrollbar-none">
   280→        <nav
   281→          aria-label={t("common.breadcrumb")}
   282→          className="flex min-w-max items-center gap-1"
   283→        >
   284→          {allSegments.map((segment, index) => {
   285→            const isCurrent = index === allSegments.length - 1;
   286→            const key = segment.id ?? `${segment.href}-${segment.label}-${index}`;
   287→
   288→            return (
   289→              <div key={key} className="flex items-center gap-1">
   290→                {index > 0 ? (
   291→                  <ChevronRight className="h-4 w-4 text-muted-foreground/70" />
   292→                ) : null}
   293→                {renderDropdown(
   294→                  segment,
   295→                  isCurrent,
   296→                  rootSegment ? index : index + 1
   297→                )}
   298→              </div>
   299→            );
   300→          })}
   301→        </nav>
   302→      </div>
   303→      {centerSlot ? (
   304→        <div className="flex min-w-0 items-center justify-center justify-self-center">
   305→          {centerSlot}
   306→        </div>
   307→      ) : (
   308→        <div />
   309→      )}
   310→      {rightSlot ? (
   311→        <div className="flex shrink-0 items-center justify-self-end gap-2">{rightSlot}</div>
   312→      ) : (
   313→        <div />
   314→      )}
   315→    </header>
   316→  );
   317→}
