     1→import { type DesktopLocation, normalizeSettingsSection, normalizeWorkspaceSection } from "./navigation-meta";
     2→
     3→export interface DesktopDeepLinkIntent {
     4→  route: DesktopLocation;
     5→  openMode?: "focus" | "reuse" | "new-tab";
     6→}
     7→
     8→function decodePart(value: string): string {
     9→  try {
    10→    return decodeURIComponent(value);
    11→  } catch {
    12→    return value;
    13→  }
    14→}
    15→
    16→export function parseVibenDeepLink(rawUrl: string): DesktopDeepLinkIntent | null {
    17→  let url: URL;
    18→
    19→  try {
    20→    url = new URL(rawUrl);
    21→  } catch {
    22→    return null;
    23→  }
    24→
    25→  if (url.protocol !== "viben:") {
    26→    return null;
    27→  }
    28→
    29→  const host = url.hostname;
    30→  const pathnameParts = url.pathname.split("/").filter(Boolean).map(decodePart);
    31→  const openMode = parseOpenMode(url.searchParams.get("mode"));
    32→
    33→  if (host === "oauth") {
    34→    return null;
    35→  }
    36→
    37→  if (host === "settings") {
    38→    return {
    39→      route: {
    40→        kind: "settings",
    41→        section: normalizeSettingsSection(pathnameParts[0]),
    42→      },
    43→      openMode,
    44→    };
    45→  }
    46→
    47→  if (host !== "workspace") {
    48→    return null;
    49→  }
    50→
    51→  const workspaceId = pathnameParts[0];
    52→  if (!workspaceId) {
    53→    return null;
    54→  }
    55→
    56→  const sectionOrKind = pathnameParts[1];
    57→  if (!sectionOrKind) {
    58→    return {
    59→      route: { kind: "workspace-home", workspaceId },
    60→      openMode,
    61→    };
    62→  }
    63→
    64→  if (sectionOrKind === "apps") {
    65→    return {
    66→      route: { kind: "workspace-apps", workspaceId },
    67→      openMode,
    68→    };
    69→  }
    70→
    71→  if (sectionOrKind === "agent") {
    72→    const agentId = pathnameParts[2];
    73→    return {
    74→      route: agentId
    75→        ? { kind: "workspace-agent-detail", workspaceId, agentId }
    76→        : { kind: "workspace-section", workspaceId, section: "agent" },
    77→      openMode,
    78→    };
    79→  }
    80→
    81→  if (sectionOrKind === "executor") {
    82→    const executorType = pathnameParts[2];
    83→    if (!executorType) {
    84→      return null;
    85→    }
    86→
    87→    return {
    88→      route: {
    89→        kind: "workspace-executor-detail",
    90→        workspaceId,
    91→        executorType,
    92→      },
    93→      openMode,
    94→    };
    95→  }
    96→
    97→  if (sectionOrKind === "page") {
    98→    const pageSlug = pathnameParts.slice(2).join("/");
    99→    if (!pageSlug) {
   100→      return null;
   101→    }
   102→
   103→    return {
   104→      route: {
   105→        kind: "workspace-page",
   106→        workspaceId,
   107→        pageSlug,
   108→      },
   109→      openMode,
   110→    };
   111→  }
   112→
   113→  if (sectionOrKind === "web") {
   114→    const targetUrl = url.searchParams.get("url");
   115→    if (!targetUrl) {
   116→      return null;
   117→    }
   118→
   119→    return {
   120→      route: {
   121→        kind: "workspace-web",
   122→        workspaceId,
   123→        url: targetUrl,
   124→        title: url.searchParams.get("title") ?? targetUrl,
   125→        webId: url.searchParams.get("web_id") ?? undefined,
   126→        sourcePageSlug: url.searchParams.get("source_page") ?? undefined,
   127→      },
   128→      openMode,
   129→    };
   130→  }
   131→
   132→  return {
   133→    route: {
   134→      kind: "workspace-section",
   135→      workspaceId,
   136→      section: normalizeWorkspaceSection(sectionOrKind),
   137→    },
   138→    openMode,
   139→  };
   140→}
   141→
   142→function parseOpenMode(value: string | null): DesktopDeepLinkIntent["openMode"] {
   143→  if (value === "reuse" || value === "new-tab" || value === "focus") {
   144→    return value;
   145→  }
   146→
   147→  return "focus";
   148→}
