     1→import { useCallback, useMemo } from "react";
     2→import { invoke } from "@tauri-apps/api/core";
     3→import { getTabViewModel, useTabStore } from "@/stores/tab-store";
     4→import type { TabNavigationState, TabViewModel } from "@/stores/tab-store";
     5→import type { IconData } from "@/components/ui/icon-picker";
     6→import { buildColdStartBreadcrumb } from "@/navigation/navigate";
     7→import type { BreadcrumbStackItem } from "@/navigation/breadcrumb-builder";
     8→import {
     9→  type DesktopLocation,
    10→  type PushPageOptions,
    11→  locationToUrl,
    12→  normalizeSettingsSection,
    13→  normalizeWorkspaceSection,
    14→} from "@/navigation/navigation-meta";
    15→import { registry } from "@/navigation/route-registry";
    16→import { useLocalWorkspaces } from "@/hooks/use-workspaces";
    17→import type { PageConfig } from "@/hooks/use-pages";
    18→
    19→// ─── Hook 1: useTabList ─────────────────────────────────────────────────────
    20→// Returns the tab view model list. Only re-renders when the tabs array changes.
    21→
    22→export function useTabList(): TabViewModel[] {
    23→  const rawTabs = useTabStore((state) => state.tabs);
    24→  return useMemo(() => rawTabs.map(getTabViewModel), [rawTabs]);
    25→}
    26→
    27→// ─── Hook 2: useActiveTabState ──────────────────────────────────────────────
    28→// Returns reactive state about the active tab. Re-renders when active tab changes.
    29→
    30→export interface ActiveTabState {
    31→  activeTabId: string | null;
    32→  activeTab: TabViewModel | null;
    33→  canGoBack: boolean;
    34→  canGoForward: boolean;
    35→  currentUrl: string | null;
    36→  currentNavigationState: TabNavigationState | null;
    37→}
    38→
    39→export function useActiveTabState(): ActiveTabState {
    40→  const activeTabId = useTabStore((state) => state.activeTabId);
    41→  const activeTabRaw = useTabStore((state) =>
    42→    state.tabs.find((tab) => tab.id === state.activeTabId) ?? null
    43→  );
    44→  const canGoBackFn = useTabStore((state) => state.canGoBack);
    45→  const canGoForwardFn = useTabStore((state) => state.canGoForward);
    46→  const getCurrentUrl = useTabStore((state) => state.getCurrentUrl);
    47→  const getCurrentNavigationState = useTabStore(
    48→    (state) => state.getCurrentNavigationState
    49→  );
    50→
    51→  const activeTab = useMemo(
    52→    () => (activeTabRaw ? getTabViewModel(activeTabRaw) : null),
    53→    [activeTabRaw]
    54→  );
    55→
    56→  const canGoBack = activeTabId ? canGoBackFn(activeTabId) : false;
    57→  const canGoForward = activeTabId ? canGoForwardFn(activeTabId) : false;
    58→  const currentUrl = activeTabId ? getCurrentUrl(activeTabId) : null;
    59→  const currentNavigationState = activeTabId
    60→    ? getCurrentNavigationState(activeTabId)
    61→    : null;
    62→
    63→  return useMemo(
    64→    () => ({
    65→      activeTabId,
    66→      activeTab,
    67→      canGoBack,
    68→      canGoForward,
    69→      currentUrl,
    70→      currentNavigationState,
    71→    }),
    72→    [activeTabId, activeTab, canGoBack, canGoForward, currentUrl, currentNavigationState]
    73→  );
    74→}
    75→
    76→// ─── Hook 3: useTabActions ──────────────────────────────────────────────────
    77→// Returns stable action functions for tab operations. These reference Zustand
    78→// store actions + resolve navigation logic. Actions that depend on activeTabId
    79→// will have their identity change when activeTabId changes.
    80→
    81→export interface TabActions {
    82→  openLocation: (
    83→    location: DesktopLocation,
    84→    options?: { breadcrumbStack?: BreadcrumbStackItem[]; openInNewTab?: boolean }
    85→  ) => string;
    86→  replaceLocation: (
    87→    location: DesktopLocation,
    88→    patch?: Partial<TabNavigationState>
    89→  ) => string | undefined;
    90→  pushLocation: (
    91→    location: DesktopLocation,
    92→    patch?: Partial<TabNavigationState>
    93→  ) => string | undefined;
    94→  pushPage: (
    95→    item: BreadcrumbStackItem,
    96→    nextLocation: DesktopLocation,
    97→    options?: PushPageOptions
    98→  ) => string | undefined;
    99→  popTo: (index: number) => void;
   100→  resetStack: (next: TabNavigationState) => string | undefined;
   101→  navigateTo: (
   102→    url: string,
   103→    input: { label: string; icon?: IconData; descriptorId?: string; meta?: BreadcrumbStackItem["meta"] }
   104→  ) => string | undefined;
   105→  openPageTab: (page: PageConfig, workspaceId: string, breadcrumbStack?: BreadcrumbStackItem[]) => string;
   106→  openPageInNewTab: (page: PageConfig, workspaceId: string, breadcrumbStack?: BreadcrumbStackItem[]) => string;
   107→  openWorkspaceView: (workspaceId: string, viewPath: string, viewName: string, icon: IconData) => string;
   108→  openGlobalView: (path: string, name: string, icon: IconData) => string;
   109→  openWebUrl: (url: string, title?: string, workspaceId?: string) => string;
   110→  openChatTab: (chatId: string, chatName: string, workspaceId: string) => string;
   111→  switchToTab: (tabId: string) => string | null;
   112→  closeTab: (tabId: string) => void;
   113→  detachTabToNewWindow: (tabId: string) => Promise<boolean>;
   114→  getTabLink: (tabId: string) => string | null;
   115→}
   116→
   117→export function useTabActions(): TabActions {
   118→  const { getWorkspace } = useLocalWorkspaces();
   119→  const activeTabId = useTabStore((state) => state.activeTabId);
   120→  const rawTabs = useTabStore((state) => state.tabs);
   121→
   122→  const openTab = useTabStore((state) => state.openTab);
   123→  const closeTabStore = useTabStore((state) => state.closeTab);
   124→  const setActiveTab = useTabStore((state) => state.setActiveTab);
   125→  const replaceLocationStore = useTabStore((state) => state.replaceLocation);
   126→  const pushLocationStore = useTabStore((state) => state.pushLocation);
   127→  const getCurrentUrl = useTabStore((state) => state.getCurrentUrl);
   128→  const getCurrentNavigationState = useTabStore(
   129→    (state) => state.getCurrentNavigationState
   130→  );
   131→
   132→  const resolveNavigation = useCallback(
   133→    (
   134→      location: DesktopLocation,
   135→      input?: {
   136→        breadcrumbStack?: BreadcrumbStackItem[];
   137→        title?: string;
   138→        icon?: IconData;
   139→      }
   140→    ): { url: string; breadcrumbStack: BreadcrumbStackItem[] } => {
   141→      const url = locationToUrl(location);
   142→
   143→      if (input?.breadcrumbStack?.length) {
   144→        return { url, breadcrumbStack: input.breadcrumbStack };
   145→      }
   146→
   147→      const stack = buildColdStartBreadcrumb(url, {
   148→        label: input?.title,
   149→        icon: input?.icon,
   150→      });
   151→
   152→      return { url, breadcrumbStack: stack };
   153→    },
   154→    []
   155→  );
   156→
