   525→// ─── Hook 4: useTabNavigation ───────────────────────────────────────────────
   526→// Returns navigation actions bound to the active tab (history back/forward/jump).
   527→
   528→export interface TabNavigationActions {
   529→  goBackInTab: () => void;
   530→  goForwardInTab: () => void;
   531→  jumpToHistory: (historyIndex: number) => void;
   532→  navigateInTab: (url: string) => void;
   533→}
   534→
   535→export function useTabNavigation(): TabNavigationActions {
   536→  const activeTabId = useTabStore((state) => state.activeTabId);
   537→  const navigate = useTabStore((state) => state.navigate);
   538→  const goBack = useTabStore((state) => state.goBack);
   539→  const goForward = useTabStore((state) => state.goForward);
   540→  const canGoBackFn = useTabStore((state) => state.canGoBack);
   541→  const canGoForwardFn = useTabStore((state) => state.canGoForward);
   542→  const jumpToHistoryStore = useTabStore((state) => state.jumpToHistory);
   543→
   544→  const goBackInTab = useCallback(() => {
   545→    if (activeTabId && canGoBackFn(activeTabId)) {
   546→      goBack(activeTabId);
   547→    }
   548→  }, [activeTabId, canGoBackFn, goBack]);
   549→
   550→  const goForwardInTab = useCallback(() => {
   551→    if (activeTabId && canGoForwardFn(activeTabId)) {
   552→      goForward(activeTabId);
   553→    }
   554→  }, [activeTabId, canGoForwardFn, goForward]);
   555→
   556→  const jumpToHistory = useCallback(
   557→    (historyIndex: number) => {
   558→      if (!activeTabId) return;
   559→      jumpToHistoryStore(activeTabId, historyIndex);
   560→    },
   561→    [activeTabId, jumpToHistoryStore]
   562→  );
   563→
   564→  const navigateInTab = useCallback(
   565→    (url: string) => {
   566→      if (!activeTabId) return;
   567→      navigate(activeTabId, url);
   568→    },
   569→    [activeTabId, navigate]
   570→  );
   571→
   572→  return useMemo(
   573→    () => ({ goBackInTab, goForwardInTab, jumpToHistory, navigateInTab }),
   574→    [goBackInTab, goForwardInTab, jumpToHistory, navigateInTab]
   575→  );
   576→}
