   578→// ─── Composed hook: usePageTabs (backward-compatible) ───────────────────────
   579→// Composes the 4 granular hooks. Existing consumers can continue using this
   580→// without changes, but new code should prefer the granular hooks.
   581→
   582→export function usePageTabs() {
   583→  const tabs = useTabList();
   584→  const activeState = useActiveTabState();
   585→  const actions = useTabActions();
   586→  const navigation = useTabNavigation();
   587→
   588→  return useMemo(
