   599→// ─── Utilities ──────────────────────────────────────────────────────────────
   600→
   601→function safeHostname(url: string): string {
   602→  try {
   603→    return new URL(url).hostname;
   604→  } catch {
   605→    return url;
   606→  }
   607→}
   608→
   609→function buildLocationFromLegacyUrl(url: string): DesktopLocation {
   610→  if (url === "/documents" || url === "/workspace") {
   611→    return { kind: "documents" };
   612→  }
   613→  if (url === "/devices/pair") {
   614→    return { kind: "device-pair" };
   615→  }
   616→  if (url.startsWith("/settings")) {
   617→    const section = url.split("/")[2];
   618→    return { kind: "settings", section: normalizeSettingsSection(section) };
   619→  }
   620→
   621→  if (url === "/publish" || url === "/my-packages" || url === "/analytics") {
   622→    return { kind: "global-route", path: url };
   623→  }
   624→
   625→  if (url.startsWith("/workspace/")) {
   626→    const parsed = new URL(url, "http://desktop.local");
   627→    const parts = parsed.pathname.split("/").filter(Boolean);
   628→    const workspaceId = parts[1];
   629→    if (!workspaceId) {
   630→      return { kind: "documents" };
   631→    }
   632→
   633→    if (parts.length === 2) {
   634→      return { kind: "workspace-home", workspaceId };
   635→    }
   636→
   637→    if (parts[2] === "apps" && !parts[3]) {
   638→      return { kind: "workspace-apps", workspaceId };
   639→    }
   640→
   641→    if (parts[2] === "page" && parts[3]) {
   642→      return {
   643→        kind: "workspace-page",
   644→        workspaceId,
   645→        pageSlug: parts
   646→          .slice(3)
   647→          .map((part) => decodeURIComponent(part))
   648→          .join("/"),
   649→      };
   650→    }
   651→
   652→    if (parts[2] === "agent" && parts[3]) {
   653→      return {
   654→        kind: "workspace-agent-detail",
   655→        workspaceId,
   656→        agentId: decodeURIComponent(parts[3]),
   657→      };
   658→    }
   659→
   660→    if (parts[2] === "executor" && parts[3]) {
   661→      return {
   662→        kind: "workspace-executor-detail",
   663→        workspaceId,
   664→        executorType: decodeURIComponent(parts[3]),
   665→      };
   666→    }
   667→
   668→    if (parts[2] === "web") {
   669→      return {
   670→        kind: "workspace-web",
   671→        workspaceId,
   672→        url: parsed.searchParams.get("url") ?? "",
   673→        title: parsed.searchParams.get("title") ?? "Web",
   674→        sourcePageSlug: parsed.searchParams.get("source_page") ?? undefined,
   675→        webId: parsed.searchParams.get("web_id") ?? undefined,
   676→      };
   677→    }
   678→
   679→    return {
   680→      kind: "workspace-section",
   681→      workspaceId,
   682→      section: normalizeWorkspaceSection(parts[2] ?? "chat"),
   683→    };
   684→  }
   685→
   686→  return { kind: "global-route", path: url };
   687→}
