   484→/** @deprecated Use registry.match() instead — kept only for legacy compatibility */
   485→export function urlToLocation(url: string): DesktopLocation | null {
   486→  const parsed = new URL(url, "http://desktop.local");
   487→  const pathname = parsed.pathname;
   488→  const segments = pathname.split("/").filter(Boolean);
   489→  const suffix = { search: parsed.search || undefined, hash: parsed.hash || undefined };
   490→
   491→  if (pathname === "/documents") return { kind: "documents", ...suffix };
   492→  if (pathname === "/devices/pair") return { kind: "device-pair", ...suffix };
   493→  if (pathname === "/publish" || pathname === "/my-packages" || pathname === "/analytics") {
   494→    return { kind: "global-route", path: `${pathname}${parsed.search}${parsed.hash}` };
   495→  }
   496→
   497→  if (segments[0] === "settings") {
   498→    const section = normalizeSettingsSection(segments[1] ? decodePathPart(segments[1]) : "general");
   499→    return { kind: "settings", section, ...suffix };
   500→  }
   501→
   502→  if (segments[0] === "agent" && segments[1]) {
   503→    return { kind: "agent-detail", agentId: decodePathPart(segments[1]), workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   504→  }
   505→  if (segments[0] === "executor" && segments[1]) {
   506→    return { kind: "executor-detail", executorType: decodePathPart(segments[1]), workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   507→  }
   508→  if (segments[0] === "skill" && segments[1]) {
   509→    return { kind: "skill-detail", skillId: decodePathPart(segments[1]), agentId: parsed.searchParams.get("agent_id") ?? "", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   510→  }
   511→  if (segments[0] === "mcp-server" && segments[1]) {
   512→    return { kind: "mcp-server-detail", serverName: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   513→  }
   514→  if (segments[0] === "subagent" && segments[1]) {
   515→    return { kind: "subagent-detail", configId: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   516→  }
   517→  if (segments[0] === "prompt" && segments[1]) {
   518→    return { kind: "prompt-detail", promptId: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   519→  }
   520→  if (segments[0] === "command" && segments[1]) {
   521→    return { kind: "command-detail", commandId: decodePathPart(segments[1]), executorType: parsed.searchParams.get("executor_type") ?? "CLAUDE_CODE", workspacePath: parsed.searchParams.get("workspace_path") ?? undefined, hash: parsed.hash || undefined };
   522→  }
   523→
   524→  if (segments[0] === "workspace" && segments[1] === "page") {
   525→    const workspaceId = parsed.searchParams.get("workspace_id");
   526→    const pageSlug = extractLegacyPageSlug(parsed.searchParams.get("page_path"));
   527→    if (workspaceId && pageSlug) {
